package com.vovanthinh.controller;
import java.io.IOException;import jakarta.servlet.*;import jakarta.servlet.annotation.WebServlet;import jakarta.servlet.http.*;import com.vovanthinh.service.ProductService;import com.vovanthinh.service.impl.ProductServiceImpl;
@WebServlet("/product") public class PublicProductController extends HttpServlet{private final ProductService service=new ProductServiceImpl();protected void doGet(HttpServletRequest r,HttpServletResponse s)throws ServletException,IOException{int page=1;try{page=Integer.parseInt(r.getParameter("page"));}catch(Exception ignored){}int size=6;long total=service.countTotalProducts();int pages=(int)Math.ceil(total/(double)size);if(pages>0)page=Math.min(Math.max(1,page),pages);r.setAttribute("products",service.getPaging(page,size));r.setAttribute("currentPage",page);r.setAttribute("totalPages",pages);r.getRequestDispatcher("/product-list.jsp").forward(r,s);}}
